let radioOrbita = 48;          // Radio actual interpolado
let radioObjetivo = 48;        // Radio objetivo (20..90 bloques)
let alturaOrbita = 25;         // Altura actual interpolada
let alturaObjetivo = 25;
let nivelOscuridadNoche = 0.55;
