function refrescarEntorno() {
  if (estadoNiebla) {
    game.entorno('NIEBLA', 1.5);
  } else if (estadoNoche) {
    game.entorno('NOCHE_LUMINOSA', 1.5);
    game.luz(nivelOscuridadNoche);
  } else {
    game.entorno('ATARDECER', 1.5);
  }
}

window.__setLuzLuciernagas = function(val) {
  radioLuzLuciernagas = Math.max(1, Math.min(15, parseInt(val) || 6));
  const lbl = document.getElementById('lbl-luz-luciernagas');
  if (lbl) lbl.textContent = radioLuzLuciernagas + ' blk';
  if (game.voxelesUI && game.voxelesUI.material) {
    game.voxelesUI.material('luciernagas', { emite: true, luz: radioLuzLuciernagas });
  }
};

window.__setOscuridadNoche = function(val) {
  const pct = parseFloat(val) || 0;
  nivelOscuridadNoche = Math.max(0.02, 1.0 - (pct / 100));
  const lbl = document.getElementById('lbl-oscuridad-noche');
  if (lbl) lbl.textContent = Math.round(pct) + '%';
  if (!estadoNiebla) {
    game.luz(nivelOscuridadNoche);
  }
};

window.__setCurvLuciernagas = function(val) {
  const pct = parseFloat(val) || 0;
  window.LUC_CONFIG.curvatura = Math.max(0.1, pct / 100);
  const lbl = document.getElementById('lbl-curv-luciernagas');
  if (lbl) lbl.textContent = Math.round(pct) + '%';
};

window.__setVelLuciernagas = function(val) {
  const pct = parseFloat(val) || 0;
  window.LUC_CONFIG.velocidad = Math.max(0.0, pct / 100);
  const lbl = document.getElementById('lbl-vel-luciernagas');
  if (lbl) lbl.textContent = Math.round(pct) + '%';
};

function engancharSliders() {
  const sliderDist = document.getElementById('slider-dist-orbita');
  const lblDist = document.getElementById('lbl-dist-orbita');
  if (sliderDist) {
    sliderDist.oninput = (e) => {
      const val = parseFloat(e.target.value) || 48;
      radioObjetivo = val;
      if (lblDist) lblDist.textContent = Math.round(val) + 'm';
    };
  }

  const sliderAlt = document.getElementById('slider-alt-orbita');
  const lblAlt = document.getElementById('lbl-alt-orbita');
  if (sliderAlt) {
    sliderAlt.oninput = (e) => {
      const val = parseFloat(e.target.value) || 25;
      alturaObjetivo = val;
      if (lblAlt) lblAlt.textContent = Math.round(val) + 'm';
    };
  }

  const sliderNoche = document.getElementById('slider-oscuridad-noche');
  if (sliderNoche) {
    sliderNoche.oninput = (e) => {
      window.__setOscuridadNoche(e.target.value);
    };
  }

  const sliderLuz = document.getElementById('slider-luz-luciernagas');
  if (sliderLuz) {
    sliderLuz.oninput = (e) => {
      window.__setLuzLuciernagas(e.target.value);
    };
  }

  const sliderCurv = document.getElementById('slider-curv-luciernagas');
  if (sliderCurv) {
    sliderCurv.oninput = (e) => {
      window.__setCurvLuciernagas(e.target.value);
    };
  }

  const sliderVel = document.getElementById('slider-vel-luciernagas');
  if (sliderVel) {
    sliderVel.oninput = (e) => {
      window.__setVelLuciernagas(e.target.value);
    };
  }
}

function registrarMenuOSD() {
  game.osd.define('menu_santuario', { sitio: 'abajo-derecha', hud: true, showTool: true, html: htmlOSD() });
}

function abrirMenuOSD() {
  registrarMenuOSD();
  game.osd.abrir('menu_santuario');
  engancharSliders();
}

function actualizarMenuOSD() {
  if (game.osd.abierta) {
    game.osd.html(htmlOSD());
    engancharSliders();
  }
}

registrarMenuOSD();

game.osd.alPulsar('TOGGLE_HOTBAR', () => {
  setHotbarSnippet(!estadoHotbar);
  actualizarMenuOSD();
});

game.osd.alPulsar('TOGGLE_HERRAMIENTA', () => {
  estadoHerramienta = !estadoHerramienta;
  game.showTool(estadoHerramienta);
  actualizarMenuOSD();
});

game.osd.alPulsar('TOGGLE_NOCHE', () => {
  estadoNoche = !estadoNoche;
  refrescarEntorno();
  actualizarMenuOSD();
});

game.osd.alPulsar('TOGGLE_NIEBLA', () => {
  estadoNiebla = !estadoNiebla;
  refrescarEntorno();
  actualizarMenuOSD();
});

game.osd.alPulsar('REFLEJOS', () => {
  game.reflejoEntorno = !game.reflejoEntorno;
  actualizarMenuOSD();
});

game.osd.alPulsar('PETALOS', () => {
  if (petalosSakura.porSegundo) { petalosSakura.para(); petalosSakura.limpia(); }
  else { petalosSakura.enciende(65); }
  actualizarMenuOSD();
});

game.osd.alPulsar('LUCIERNAGAS', () => {
  if (luciernagas.porSegundo) { luciernagas.para(); luciernagas.limpia(); }
  else { luciernagas.enciende(26); }
  actualizarMenuOSD();
});

game.osd.alPulsar('ORBITA', () => {
  toggleCamaraOrbital();
  actualizarMenuOSD();
});

game.osd.alPulsar('REC', () => {
  game.osd.cerrar();
  if (typeof game.video !== 'undefined') game.video();
});

game.osd.alPulsar('CERRAR', () => {
  game.osd.cerrar();
});

game.onKey('o', () => {
  abrirMenuOSD();
});

